import random
import struct
from typing import List

# Varint encode (unsigned)
def _varint(n: int) -> bytes:
    out = bytearray()
    n &= 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF  # ensure non-negative
    while True:
        to_write = n & 0x7F
        n >>= 7
        if n:
            out.append(to_write | 0x80)
        else:
            out.append(to_write)
            break
    return bytes(out)

# ZigZag encode for sint64
def _zigzag(n: int) -> int:
    return (n << 1) ^ (n >> 63)

def _field_key(tag: int, wire_type: int) -> bytes:
    return _varint((tag << 3) | (wire_type & 0x7))

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(max(0, n)))

def _emit_varint_field(tag: int, value: int) -> bytes:
    return _field_key(tag, 0) + _varint(value & 0xFFFFFFFFFFFFFFFF)

def _emit_sint_field(tag: int, value: int) -> bytes:
    return _field_key(tag, 0) + _varint(_zigzag(value))

def _emit_fixed32_field(tag: int, value: int) -> bytes:
    return _field_key(tag, 5) + struct.pack('<I', value & 0xFFFFFFFF)

def _emit_fixed64_field(tag: int, value: int) -> bytes:
    return _field_key(tag, 1) + struct.pack('<Q', value & 0xFFFFFFFFFFFFFFFF)

def _emit_length_delim_field(tag: int, payload: bytes) -> bytes:
    return _field_key(tag, 2) + _varint(len(payload)) + payload

def _rand_utf8(rng: random.Random, n: int) -> bytes:
    out = bytearray()
    while len(out) < n:
        choice = rng.randrange(10)
        if choice < 7:
            out.append(rng.randrange(0x20, 0x7F))
        elif choice < 9:
            cp = rng.randrange(0x80, 0x7FF)
            out += chr(cp).encode('utf-8')
        else:
            cp = rng.randrange(0x800, 0xD7FF)
            out += chr(cp).encode('utf-8')
    return bytes(out[:n])

def _make_message_variant(rng: random.Random, max_len: int) -> bytes:
    if max_len <= 0:
        return b''
    variant = rng.randrange(7)
    buf = bytearray()

    def remaining_space() -> int:
        return max(0, max_len - len(buf))

    if variant == 0:
        count = rng.randint(3, 12)
        for i in range(count):
            if remaining_space() <= 0:
                break
            tag = i + 1
            kind = rng.randrange(4)
            if kind == 0:
                val = rng.getrandbits(rng.choice([1, 7, 13, 32, 63]))
                buf += _emit_varint_field(tag, val)
            elif kind == 1:
                val = rng.randint(-2**31, 2**31 - 1)
                buf += _emit_sint_field(tag, val)
            elif kind == 2:
                buf += _emit_fixed32_field(tag, rng.getrandbits(32))
            else:
                buf += _emit_fixed64_field(tag, rng.getrandbits(64))
            if len(buf) >= max_len:
                break
    elif variant == 1:
        items = rng.randint(2, 8)
        for i in range(items):
            if remaining_space() <= 0:
                break
            tag = rng.randint(1, 10)
            size = rng.randint(0, 64)
            if rng.random() < 0.5:
                payload = _rand_utf8(rng, size)
            else:
                payload = _rand_bytes(rng, size)
                if rng.random() < 0.3 and size > 0:
                    payload = bytearray(payload)
                    for _ in range(rng.randint(1, min(3, size))):
                        payload[rng.randrange(size)] = 0
                    payload = bytes(payload)
            field = _emit_length_delim_field(tag, payload)
            if len(field) > remaining_space():
                break
            buf += field
    elif variant == 2:
        # Repeated packed varints
        tag = 1
        vals = [rng.randrange(0, 1 << rng.choice([1, 7, 13, 20, 28])) for _ in range(rng.randint(5, 40))]
        packed = b''.join(_varint(v) for v in vals)
        field1 = _emit_length_delim_field(tag, packed)
        buf += field1[:remaining_space()]
        if remaining_space() > 0:
            tag = 2
            vals2 = [rng.randrange(0, 1 << rng.choice([1, 7, 13, 20, 28])) for _ in range(rng.randint(3, 20))]
            packed2 = b''.join(_varint(v) for v in vals2)
            field2 = _emit_length_delim_field(tag, packed2)
            buf += field2[:remaining_space()]
    elif variant == 3:
        inner = _make_message_variant(rng, max(1, max_len // 2))
        field = _emit_length_delim_field(1, inner)
        buf += field[:remaining_space()]
        if remaining_space() > 0:
            buf += _emit_varint_field(2, rng.getrandbits(16))[:remaining_space()]
        if remaining_space() > 0:
            buf += _emit_fixed32_field(3, rng.getrandbits(32))[:remaining_space()]
    elif variant == 4:
        n = rng.randint(10, 60)
        for _ in range(n):
            if remaining_space() <= 0:
                break
            tag = rng.randint(1, 200)
            t = rng.randrange(3)
            if t == 0:
                field = _emit_varint_field(tag, rng.getrandbits(8))
            elif t == 1:
                field = _emit_fixed32_field(tag, rng.getrandbits(32))
            else:
                payload = _rand_bytes(rng, rng.randint(0, 10))
                field = _emit_length_delim_field(tag, payload)
            if len(field) > remaining_space():
                break
            buf += field
    elif variant == 5:
        for i in range(rng.randint(2, 10)):
            if remaining_space() <= 0:
                break
            if rng.random() < 0.5:
                patterns = [0x00000000, 0x80000000, 0x3F800000, 0x7F800000, 0xFF800000, 0x7FC00000]
                val = rng.choice(patterns + [rng.getrandbits(32)])
                field = _emit_fixed32_field(10 + i, val)
            else:
                patterns = [0x0000000000000000, 0x8000000000000000, 0x3FF0000000000000, 0x7FF0000000000000, 0xFFF0000000000000, 0x7FF8000000000000]
                val = rng.choice(patterns + [rng.getrandbits(64)])
                field = _emit_fixed64_field(20 + i, val)
            if len(field) > remaining_space():
                break
            buf += field
    else:
        buf += _emit_varint_field(1, 0)
        buf += _emit_varint_field(2, (1 << 63) - 1)
        long_target = max(0, min(600, max_len // 2))
        if long_target > 0:
            long_s = _rand_utf8(rng, rng.randint(max(1, long_target // 2), long_target))
        else:
            long_s = b''
        field3 = _emit_length_delim_field(3, long_s)
        buf += field3[:remaining_space()]
        zeros = bytes(max(0, min(64, remaining_space())))
        field4 = _emit_length_delim_field(4, zeros)
        buf += field4[:remaining_space()]

    return bytes(buf[:max_len])

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    max_total = 2048
    # Choose a target length safely
    small = rng.randint(1, 64)
    mid = rng.randint(65, 256)
    large_upper = max(257, min(1024, max_total))
    large = rng.randint(257, large_upper)
    huge = rng.randint(1025, max_total)
    target_len = rng.choice([small, mid, large, huge])

    parts: List[bytes] = []
    remaining = target_len
    count = rng.randint(1, 4)
    for _ in range(count):
        if remaining <= 0:
            break
        upper = max(1, min(512, remaining))
        lower = 1 if upper < 32 else 32
        if lower > upper:
            lower = 1
        part_max = rng.randint(lower, upper)
        part = _make_message_variant(rng, part_max)
        parts.append(part)
        remaining -= len(part)
        if remaining <= 0:
            break
        if rng.random() < 0.25:
            raw_len = rng.randint(1, min(64, remaining))
            parts.append(_rand_bytes(rng, raw_len))
            remaining -= raw_len

    data = b''.join(parts)

    if not data:
        data = b'\x00'
    if len(data) > max_total:
        data = data[:max_total]
    return data
